import math

def is_perfect_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

# Search n, which must be a multiple of 3, in the range [45, 89]
min_n = 45
max_n = 89
smallest_n = None

for n in range(min_n, max_n + 1):
    if n % 3 == 0:
        # We need n^2 + 3k^2 = 8028
        # 3k^2 = 8028 - n^2
        term = 8028 - n*n
        if term > 0 and term % 3 == 0:
            k_squared = term // 3
            if is_perfect_square(k_squared):
                smallest_n = n
                break

if smallest_n:
    print(f"The smallest n found is: {smallest_n}")
else:
    print("No solution found in the specified range.")
